import{_ as t,a,o as n,a6 as i}from"./chunks/framework.CJDy2q7X.js";const m=JSON.parse('{"title":"Create Sitemap","description":"","frontmatter":{"outline":false,"examples":[{"id":"create","title":"Create Sitemap","description":"Create a sitemap definition. Creating the row does not build the XML files — call generate afterwards.","query":"mutation CreateAdminMarketingSitemap(\\n  $input: createAdminMarketingSitemapInput!\\n) {\\n  createAdminMarketingSitemap(input: $input) {\\n    adminMarketingSitemap {\\n      id\\n      _id\\n      fileName\\n      path\\n      channels\\n      urls\\n      generatedAt\\n      generatedFiles\\n      indexFile\\n      generatedSitemaps\\n      createdAt\\n      updatedAt\\n    }\\n  }\\n}\\n","variables":"{\\n  \\"input\\": {\\n    \\"fileName\\": \\"sitemap.xml\\",\\n    \\"path\\": \\"/\\",\\n    \\"channels\\": [1]\\n  }\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"createAdminMarketingSitemap\\": {\\n      \\"adminMarketingSitemap\\": {\\n        \\"id\\": \\"/api/admin/marketing/sitemaps/1\\",\\n        \\"_id\\": 1,\\n        \\"fileName\\": \\"sitemap.xml\\",\\n        \\"path\\": \\"/\\",\\n        \\"channels\\": [1],\\n        \\"urls\\": [\\n          \\"https://example.com/storage/sitemaps/default/sitemap-1-1.xml\\"\\n        ],\\n        \\"generatedAt\\": null,\\n        \\"generatedFiles\\": [],\\n        \\"indexFile\\": null,\\n        \\"generatedSitemaps\\": [],\\n        \\"createdAt\\": \\"2026-06-20T10:00:00+05:30\\",\\n        \\"updatedAt\\": \\"2026-06-20T10:00:00+05:30\\"\\n      }\\n    }\\n  }\\n}\\n"}]},"headers":[],"relativePath":"api/graphql-api/admin/marketing/search-seo/sitemaps-create.md","filePath":"api/graphql-api/admin/marketing/search-seo/sitemaps-create.md","lastUpdated":1789385991000}'),r={name:"api/graphql-api/admin/marketing/search-seo/sitemaps-create.md"};function d(s,e,o,l,h,p){return n(),a("div",null,e[0]||(e[0]=[i('<h1 id="create-sitemap" tabindex="-1">Create Sitemap <a class="header-anchor" href="#create-sitemap" aria-label="Permalink to &quot;Create Sitemap&quot;">​</a></h1><p>Creates a sitemap definition — the <strong>Create Sitemap</strong> action on the admin <strong>Marketing → Search &amp; SEO → Sitemaps</strong> screen.</p><p>New here? Read the <a href="/api/graphql-api/admin/marketing/search-seo/sitemaps/">Sitemaps overview</a> for what a sitemap does and how its fields behave.</p><h3 id="creating-does-not-build-the-xml" tabindex="-1">Creating does not build the XML <a class="header-anchor" href="#creating-does-not-build-the-xml" aria-label="Permalink to &quot;Creating does not build the XML&quot;">​</a></h3><p>Saving the row only stores the definition. To write the actual XML files, call the <a href="/api/graphql-api/admin/marketing/search-seo/sitemaps-generate.html">generate</a> mutation explicitly — <code>generatedAt</code> and <code>generatedFiles</code> stay empty until then.</p><h3 id="one-sitemap-one-set-of-files-per-channel" tabindex="-1">One sitemap, one set of files per channel <a class="header-anchor" href="#one-sitemap-one-set-of-files-per-channel" aria-label="Permalink to &quot;One sitemap, one set of files per channel&quot;">​</a></h3><p>A sitemap covers the channels listed in <code>channels</code>, and generation writes an index plus its child files for each of them, using that channel&#39;s own hostname. <code>urls</code> returns the public index URL per channel, which is the link to submit to a search engine.</p><h2 id="operation" tabindex="-1">Operation <a class="header-anchor" href="#operation" aria-label="Permalink to &quot;Operation&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operation</th><th>Type</th><th>Purpose</th></tr></thead><tbody><tr><td><code>createAdminMarketingSitemap</code></td><td>Mutation</td><td>Create a sitemap definition</td></tr></tbody></table><h2 id="details" tabindex="-1">Details <a class="header-anchor" href="#details" aria-label="Permalink to &quot;Details&quot;">​</a></h2><ul><li>Requires an admin Bearer token and the <code>marketing.search_seo.sitemaps.create</code> permission.</li><li>The mutation returns the full sitemap payload.</li></ul><h2 id="input-fields" tabindex="-1">Input fields <a class="header-anchor" href="#input-fields" aria-label="Permalink to &quot;Input fields&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Notes</th></tr></thead><tbody><tr><td><code>fileName</code></td><td>String</td><td>Yes</td><td>Index file name — letters, digits, <code>-</code>, <code>_</code>, <code>.</code>; must end with <code>.xml</code></td></tr><tr><td><code>path</code></td><td>String</td><td>Yes</td><td>Directory the index file lives in — must start and end with <code>/</code>, no <code>//</code></td></tr><tr><td><code>channels</code></td><td>[Int]</td><td>Yes</td><td>Channel ids the sitemap covers. At least one — generation walks the channels, so a sitemap covering none produces no files</td></tr></tbody></table>',13)]))}const u=t(r,[["render",d]]);export{m as __pageData,u as default};
